#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    int N = 2 * n;
    const int MOD = 1000000007;

    // Initialize 3D DP array with zeros
    std::vector<std::vector<std::vector<int>>> dp(N + 1, std::vector<std::vector<int>>(N + 1, std::vector<int>(2, 0)));

    // Base case
    dp[0][0][0] = 0;
    dp[0][0][1] = 0;

    for (int i = 1; i <= N; ++i) {
        for (int j = 0; j <= i; ++j) {
            for (int k = 0; k <= 1; ++k) {
                int val = 0;
                if (k == 1) {
                    if (i - j >= 2) {
                        val = (val + dp[i - 1][j + 1][0]) % MOD;
                    }
                    if (j > 0) {
                        val = (val + dp[i - 1][j - 1][0]) % MOD;
                    }
                } else {
                    int getVal(int i, int j, bool selectStart, bool selectEnd) {
                        int res = 0;
                        if (i - j >= 2) {
                            if (selectStart) {
                                res = (res + dp[i - 1][j + 1][1] + 1) % MOD;
                            } else {
                                res = (res + dp[i - 1][j + 1][0]) % MOD;
                            }
                        }
                        if (j > 0) {
                            if (selectEnd) {
                                res = (res + dp[i - 1][j - 1][1] + 1) % MOD;
                            } else {
                                res = (res + dp[i - 1][j - 1][0]) % MOD;
                            }
                        }
                        return res;
                    }
                    int val1 = getVal(i, j, false, false);
                    int val2 = getVal(i, j, false, true);
                    int val3 = getVal(i, j, true, false);
                    val = std::max({val1, val2, val3});
                }
                dp[i][j][k] = val;
            }
        }
    }

    std::cout << dp[N][0][0];
    return 0;
}

